"""Plain-English analyst read-out, generated by rules so it is reproducible and auditable."""
from __future__ import annotations

import math

import pandas as pd

from .regime import REGIME_NAMES, score_band

STANCE = {
    1: "Expansion with contained inflation. Equities have the wind behind them; growth and cyclical sectors usually lead.",
    2: "Inflation or policy is the binding constraint. Expect rate pressure on valuations; value, energy and short-duration assets usually hold up better than long-duration growth.",
    3: "Growth or credit is breaking down. Capital preservation comes first; defensives, T-bills and quality usually lead until policy pivots.",
    4: "Policy has pivoted after a washout. Historically the best risk/reward window: small caps, cyclicals and beaten-down leaders usually rebound hardest.",
}


def _fmt(x, spec="{:.1f}", none="n/a"):
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return none
    return spec.format(x)


def build_narrative(P: pd.DataFrame, F: pd.DataFrame, S: pd.DataFrame, regime: int, amber: bool,
                    assets: pd.DataFrame, th: dict, cape: float | None) -> dict:
    x = P.iloc[-1]
    f = F.iloc[-1]
    score = int(S["Total"].iloc[-1])
    band = score_band(score)
    headline = f"{REGIME_NAMES[regime]}{' with Amber warning' if amber else ''} · risk score {score}/100 ({band})"

    lines = []
    infl = "hot" if f.INFL_HOT else ("cool" if f.INFL_COOL else "moderate")
    lines.append(f"Inflation is {infl}: core PCE {_fmt(x.core_pce_yoy)}% YoY, core CPI {_fmt(x.core_cpi_3m_ann)}% annualised over 3 months, "
                 f"Brent {_fmt(x.brent_yoy, '{:+.0f}')}% YoY.")
    stance = "tightening" if (x.ff_change_6m or 0) > 0 else ("easing" if (x.ff_change_3m or 0) < 0 else "on hold")
    lines.append(f"Policy is {stance}: fed funds upper bound {_fmt(x.ff_upper, '{:.2f}')}%, 2-year yield {_fmt(x.two_y_minus_ff * 100 if x.two_y_minus_ff == x.two_y_minus_ff else float('nan'), '{:+.0f}')} bp versus it "
                 f"({'more hikes priced' if (x.two_y_minus_ff or 0) >= 0.5 else 'cuts priced' if (x.two_y_minus_ff or 0) <= -0.5 else 'little priced either way'}); "
                 f"real policy rate {_fmt(x.real_ff, '{:+.1f}')}%.")
    lines.append(f"Growth: unemployment {_fmt(x.unrate)}%, Sahm indicator {_fmt(x.sahm, '{:.2f}')}, claims {_fmt(x.claims_vs_low * 100 if x.claims_vs_low == x.claims_vs_low else float('nan'), '{:+.0f}')}% above their 52-week low; "
                 f"12-month recession probability from the yield curve {_fmt(x.recession_prob_12m * 100 if x.recession_prob_12m == x.recession_prob_12m else float('nan'), '{:.0f}')}%.")
    lines.append(f"Stress: HY spread {_fmt(x.hy_bp, '{:.0f}')} bp ({_fmt(x.hy_bp - x.hy_min_126, '{:+.0f}')} bp from its 6-month low), VIX {_fmt(x.vix)}, "
                 f"S&P 500 {_fmt(x.drawdown_pct, '{:+.1f}')}% from its 52-week high, curve pattern: {x.curve_pattern or 'n/a'}.")

    # what would change the call
    c, v = th["credit"], th["volatility"]
    triggers = []
    if regime in (1, 2):
        triggers.append(f"Breakdown (R3) at once if VIX closes at or above {v['vix_crisis']} (now {_fmt(x.vix)}) or HY reaches {c['hy_crisis_bp']} bp (now {_fmt(x.hy_bp, '{:.0f}')}).")
        hy_line = min(c["hy_stress_bp"], (x.hy_min_126 or 0) + c["hy_rise_stress_bp"])
        sma = P.attrs.get("spx_sma10m_live")
        triggers.append(f"Breakdown (R3) after 2 weeks if a month-end close falls below the 10-month average (≈ {_fmt(sma, '{:,.0f}')}; S&P now {_fmt(x.spx, '{:,.0f}')}) "
                        f"while HY is at or above ≈ {hy_line:.0f} bp, or growth weakens.")
    if regime == 2:
        triggers.append("Back to Goldilocks (R1) after 3 month-ends with core PCE below 3.0%, core CPI 3-month below 4.0% and no hawkish policy signal.")
    if regime == 1:
        triggers.append("Hawkish (R2) after 2 month-ends with core PCE at or above 3.0% or hikes priced with a restrictive real rate.")
    if regime == 3:
        triggers.append(f"Recovery (R4) needs all three: a pivot (cut, facility or 2Y 100 bp below fed funds), a VIX washout at or above {v['vix_washout']} followed by a release, "
                        f"and HY at least {c['hy_heal_from_max_bp']} bp below its 6-month high and falling.")
    if regime == 4:
        triggers.append("Failed recovery returns to R3 if HY sets a new high (+50 bp) or the index falls below 95% of the breakdown low.")

    ok = assets[assets.status == "ok"] if not assets.empty else assets
    def top(col, n=3, best=True, groups=("US sector", "US industry")):
        sub = ok[ok.group.isin(groups)].dropna(subset=[col])
        sub = sub.sort_values(col, ascending=not best).head(n)
        return ", ".join(f"{r['name']} ({r['ticker']})" for _, r in sub.iterrows()) or "n/a"

    spy = ok[ok.ticker == "SPY"]
    spy_row = spy.iloc[0] if len(spy) else None
    horizons = {
        "Short term (1-3 months)": (f"US market {spy_row['short_view'].lower() if spy_row is not None else 'n/a'}. "
                                    f"Strongest: {top('short_score')}. Weakest: {top('short_score', best=False)}."),
        "Medium term (6-12 months)": (f"US market {spy_row['medium_view'].lower() if spy_row is not None else 'n/a'}. "
                                      f"Best regime fit: {top('medium_score')}. Weakest: {top('medium_score', best=False)}."),
        "Long term (3-5+ years)": (f"US market {spy_row['long_view'].lower() if spy_row is not None else 'n/a'} on valuation"
                                   f"{' (CAPE ' + format(cape, '.1f') + ')' if cape else ''}. Valuation sets the size of the long-run return, not its timing."),
    }
    global_line = f"Global strongest (medium term): {top('medium_score', groups=('Global',))}. Weakest: {top('medium_score', best=False, groups=('Global',))}."
    amber_signs = F.attrs.get("amber_signs")
    amber_list = [k for k, val in amber_signs.iloc[-1].items() if val] if amber_signs is not None else []
    if amber and len(amber_list) < th["amber"]["need"]:
        amber_list.append(f"Amber stays on until fewer than {th['amber']['need']} signs fire for "
                          f"{th['persistence']['amber_clear_weeks']} straight weeks")
    return {
        "headline": headline,
        "stance": STANCE[regime],
        "situation": lines,
        "horizons": horizons,
        "global": global_line,
        "triggers": triggers,
        "amber_signs": amber_list,
    }
